meta.script:


document.addEventListener('DOMContentLoaded', function () {
  // tabindex fix
  var skip = document.getElementById('pojo-a11y-skip-content');
  if (skip) skip.setAttribute('tabindex', '0');

  // aria-label fix
  var toolbar = document.getElementById('pojo-a11y-toolbar');
  if (toolbar) toolbar.setAttribute('aria-label', 'Accessibility Toolbar');

  // h3 → h2 fix
  document.querySelectorAll('h3.hero-intro__subtitle').forEach(function (h3) {
    var h2 = document.createElement('h2');
    h2.className = h3.className;
    h2.innerHTML = h3.innerHTML;
    h3.parentNode.replaceChild(h2, h3);
  });

  // target="_blank" aria-label fix
  document.querySelectorAll('a[target="_blank"]').forEach(function (a) {
    var label = a.getAttribute('aria-label') || a.textContent.trim();
    a.setAttribute('aria-label', label + ' (otwiera się w nowej karcie)');
  });
});

jQuery(function() {
  /* init Algolia client */
  var client = algoliasearch(algolia.application_id, algolia.search_api_key);

  /* setup default sources */
  var sources = [];
  jQuery.each(algolia.autocomplete.sources, function(i, config) {
    var suggestion_template = wp.template(config['tmpl_suggestion']);
    sources.push({
      source: algoliaAutocomplete.sources.hits(client.initIndex(config['index_name']), {
        hitsPerPage: config['max_suggestions'],
        attributesToSnippet: [
          'content:10'
        ],
        highlightPreTag: '__ais-highlight__',
        highlightPostTag: '__/ais-highlight__',
        filters: 'wpml.locale:"' + current_locale + '"',
        // filters: 'wpml.locale: "pl"'
      }),
      templates: {
        header: function() {
          return wp.template('autocomplete-header')({
            label: _.escape(config['label'])
          });
        },
        suggestion: function(hit) {
          if (hit.escaped === true) {
            return suggestion_template(hit);
          }
          hit.escaped = true;

          for (var key in hit._highlightResult) {
            /* We do not deal with arrays. */
            if (typeof hit._highlightResult[key].value !== 'string') {
              continue;
            }
            hit._highlightResult[key].value = _.escape(hit._highlightResult[key].value);
            hit._highlightResult[key].value = hit._highlightResult[key].value.replace(/__ais-highlight__/g, '').replace(/__\/ais-highlight__/g, '');
          }

          for (var key in hit._snippetResult) {
            /* We do not deal with arrays. */
            if (typeof hit._snippetResult[key].value !== 'string') {
              continue;
            }

            hit._snippetResult[key].value = _.escape(hit._snippetResult[key].value);
            hit._snippetResult[key].value = hit._snippetResult[key].value.replace(/__ais-highlight__/g, '').replace(/__\/ais-highlight__/g, '');
          }

          return suggestion_template(hit);
        }
      }
    });

  });

  /* Setup dropdown menus */
  jQuery(algolia.autocomplete.input_selector).each(function(i) {
    var $searchInput = jQuery(this);

    var config = {
      debug: algolia.debug,
      hint: false,
      openOnFocus: true,
      appendTo: 'body',
      templates: {
        empty: wp.template('autocomplete-empty')
      }
    };

    if (algolia.powered_by_enabled) {
      config.templates.footer = wp.template('autocomplete-footer');
    }

    /* Instantiate autocomplete.js */
    var autocomplete = algoliaAutocomplete($searchInput[0], config, sources)
      .on('autocomplete:selected', function(e, suggestion) {
        /* Redirect the user when we detect a suggestion selection. */
        window.location.href = suggestion.permalink;
      });

    /* Force the dropdown to be re-drawn on scroll to handle fixed containers. */
    jQuery(window).scroll(function() {
      if (autocomplete.autocomplete.getWrapper().style.display === "block") {
        autocomplete.autocomplete.close();
        autocomplete.autocomplete.open();
      }
    });
  });

  jQuery(document).on("click", ".algolia-powered-by-link", function(e) {
    e.preventDefault();
    window.location = "https://www.algolia.com/?utm_source=WordPress&utm_medium=extension&utm_content=" + window.location.hostname + "&utm_campaign=poweredby";
  });
});

body.script:

document.addEventListener('DOMContentLoaded', function () {
    setTimeout(function(){
        if( document.querySelectorAll('[name^=ct_checkjs]').length > 0 ) {
            apbct_public_sendREST(
                'js_keys__get',
                { callback: apbct_js_keys__set_input_value }
            )
        }
    },0)					    
})

window.dataLayer = window.dataLayer || [];

function gtag() {
  dataLayer.push(arguments);
}
gtag('js', new Date());

gtag('config', 'UA-37026741-1');



var target = document.querySelector(".menu-item-has-children");
target.addEventListener("mouseover", mOver, false);
target.addEventListener("mouseout", mOut, false);

function mOver() {
  element.classList.add('opened');
}

function mOut() {
  element.classList.remove('opened');
}
